import React, { useEffect, useRef, useState } from "react";
import "./GazePortrait.css";
import { currentRoleLine } from "../../portfolio";

import upLeft from "../../assets/hero-gaze/up-left.webp";
import up from "../../assets/hero-gaze/up.webp";
import upRight from "../../assets/hero-gaze/up-right.webp";
import left from "../../assets/hero-gaze/left.webp";
import center from "../../assets/hero-gaze/center.webp";
import down from "../../assets/hero-gaze/down.webp";
import downLeft from "../../assets/hero-gaze/down-left.webp";
import downRight from "../../assets/hero-gaze/down-right.webp";
import blink from "../../assets/hero-gaze/blink.webp";
import smile from "../../assets/hero-gaze/smile.webp";
import right from "../../assets/hero-gaze/right.webp";
import working from "../../assets/hero-gaze/working.webp";

/* ==========================================================
   GAZE PORTRAIT — the hero's right-hand art.
   Pre-rendered frames of the same portrait looking in
   different directions; the cursor picks the nearest one.
   Nothing here is 3D: it is an image swap with a crossfade.
   ========================================================== */

// Screen-space directions, plus expressions and the idle "working" frame.
const FRAMES = {
  "up-left": upLeft,
  up,
  "up-right": upRight,
  left,
  center,
  right,
  "down-left": downLeft,
  down,
  "down-right": downRight,
  blink,
  smile,
  working,
};

const GRID = [
  ["up-left", "up", "up-right"],
  ["left", "center", "right"],
  ["down-left", "down", "down-right"],
];

const SOURCES = Array.from(new Set(Object.values(FRAMES)));

// Where each frame's head points, as [col, row] on GRID. Used to route big
// turns through the middle and to nudge the head along its travel.
const POS = { smile: [1, 1], blink: [1, 1], working: [1, 2] };
GRID.forEach((cols, r) => cols.forEach((key, c) => (POS[key] = [c, r])));

// Where the eyes sit inside the square frame, as fractions of its box.
const EYE_X = 0.5;
const EYE_Y = 0.28;
// The face itself — hovering it gets eye contact and a hello.
const FACE = { x0: 0.38, x1: 0.62, y0: 0.08, y1: 0.46 };

const ZONE_LINES = {
  left: ["Happy to walk you through any of it."],
  "up-left": ["Projects and experience are up top."],
  up: ["Everything's in the menu above."],
  "up-right": ["Feel free to look around."],
  right: ["Glad you stopped by."],
  "down-left": ["Try Jarvis, my AI coding agent, below."],
  down: ["Happy to share how these were measured."],
  "down-right": ["Questions? I'm easy to reach."],
};

const FACE_LINES = ["Hi there — great to meet you."];
const TAP_LINES = [
  `Hi, I'm Laxman — ${currentRoleLine}.`,
  "I build GenAI platforms that run in production.",
  "Open to new opportunities.",
  "Thanks for visiting!",
];

// Hero CTAs carry data-gaze with the line to say while hovered.
const CTA_SELECTOR = ".greeting-main [data-gaze]";

// Crossfade lengths, handed to the CSS as --gaze-fade. A new frame never
// starts before the last one has finished fading in: interrupting a
// half-faded frame would snap it to full opacity underneath the next one.
const FADE_MS = 240;
// A turn across the whole grid (left to right, up to down) passes through
// the middle frame on the way, with a quicker fade, so it reads as the head
// turning rather than one picture swapping for another.
const STEP_MS = 150;
const BLINK_FADE_MS = 50;
// During a crossfade both frames slide this far along the head's travel
// (as % of the portrait), so the dissolve reads as movement.
const NUDGE = 0.7;
// How far past a zone edge the cursor has to go before he turns, as a
// fraction of the portrait. Stops him flickering when the cursor rests on
// a boundary.
const HYSTERESIS = 0.05;
// Slight drift of the whole portrait toward the cursor, in px — continuous
// motion between the discrete frames.
const DRIFT_X = 7;
const DRIFT_Y = 4;
// The soft light behind him follows the cursor further than he drifts, in
// px, so the page seems lit from where you are.
const LIGHT_X = 56;
const LIGHT_Y = 32;

const IDLE_MS = 3500;
// Left alone a while longer, he goes back to his laptop.
const WORK_MS = 7000;
const WORK_LINES = [
  "Back to building — say hi anytime.",
  "Still here if you need me.",
];
const DWELL_MS = 650;
const BUBBLE_MS = 2600;
// Bubbles should read as an occasional hello, not commentary on the cursor.
const BUBBLE_GAP_MS = 9000;
// Touch devices get a slow look-around instead of cursor tracking.
const WANDER = [
  "left",
  "center",
  "working",
  "up-left",
  "center",
  "right",
  "down-left",
  "working",
];

const pick = (list) => list[Math.floor(Math.random() * list.length)];

export default function GazePortrait() {
  const rootRef = useRef(null);
  const [frame, setFrame] = useState("center");
  const [prev, setPrev] = useState(null);
  const [bubble, setBubble] = useState(null);
  // Only the neutral frame is in the first paint (~60KB). The other twelve
  // are fetched once the page has loaded and the browser is idle, and join
  // the stack only after they have decoded, so no swap ever shows a frame
  // that is still arriving.
  const [ready, setReady] = useState(false);
  // The portrait fades in once its first frame has decoded, rather than
  // popping in whenever the image happens to arrive.
  const [shown, setShown] = useState(false);
  const firstImgRef = useRef(null);
  useEffect(() => {
    const img = firstImgRef.current;
    if (img && img.complete && img.naturalWidth) setShown(true);
  }, []);
  const readyRef = useRef(false);

  const frameRef = useRef("center");
  const lockRef = useRef(null); // a hovered CTA or "tap" while it overrides gaze
  const bubbleTimer = useRef(0);
  const lastBubbleAt = useRef(0);
  const lastLine = useRef("");
  const said = useRef(new Set());

  // All state changes go through here, so the outgoing frame is marked
  // (is-prev) for its leave animation and the fade timing is known.
  const lastSwitch = useRef(0);
  const lastFade = useRef(0);
  const pending = useRef(null);
  const pendingTimer = useRef(0);
  const isBlink = (a, b) => a === "blink" || b === "blink";
  const commit = (next, fade) => {
    const from = frameRef.current;
    const root = rootRef.current;
    if (root) {
      const [c0, r0] = POS[from] || [1, 1];
      const [c1, r1] = POS[next] || [1, 1];
      const still = isBlink(from, next);
      root.style.setProperty("--gaze-fade", `${fade}ms`);
      root.style.setProperty(
        "--gaze-nx",
        still ? 0 : Math.sign(c1 - c0) * NUDGE
      );
      root.style.setProperty(
        "--gaze-ny",
        still ? 0 : Math.sign(r1 - r0) * NUDGE
      );
    }
    setPrev(from);
    frameRef.current = next;
    lastSwitch.current = performance.now();
    lastFade.current = fade;
    setFrame(next);
  };
  // The frame to pass through on the way from one grid frame to another two
  // columns or rows away, or null for a direct swap.
  const via = (from, to) => {
    const a = GRID.flat().includes(from) && POS[from];
    const b = GRID.flat().includes(to) && POS[to];
    if (!a || !b) return null;
    const far = (i) => Math.abs(a[i] - b[i]) === 2;
    if (!far(0) && !far(1)) return null;
    return GRID[far(1) ? 1 : a[1]][far(0) ? 1 : a[0]];
  };
  const step = () => {
    pendingTimer.current = 0;
    const to = pending.current;
    const from = frameRef.current;
    if (to === from) return;
    if (isBlink(from, to)) {
      commit(to, BLINK_FADE_MS);
      return;
    }
    const mid = via(from, to);
    commit(mid || to, mid ? STEP_MS : FADE_MS);
    // Carry on to the target once the stopover has faded in.
    if (mid) pendingTimer.current = setTimeout(step, STEP_MS);
  };
  const show = useRef(() => {});
  show.current = (next) => {
    if (!readyRef.current && next !== "center") return;
    pending.current = next;
    if (next === frameRef.current) return;
    // Blinks are cuts and skip the queue.
    const wait = isBlink(next, frameRef.current)
      ? 0
      : lastSwitch.current + lastFade.current - performance.now();
    if (wait <= 0) {
      clearTimeout(pendingTimer.current);
      step();
    } else if (!pendingTimer.current) {
      // Only the latest request is honoured when the fade finishes, so a
      // fast sweep across the page lands on one frame instead of flipping
      // through every zone it crossed.
      pendingTimer.current = setTimeout(step, wait);
    }
  };
  useEffect(() => () => clearTimeout(pendingTimer.current), []);

  const say = useRef(() => {});
  say.current = (line, { force = false } = {}) => {
    const now = Date.now();
    if (!force && now - lastBubbleAt.current < BUBBLE_GAP_MS) return;
    // Unprompted lines play once per visit; hovers and taps may repeat.
    if (!force && (line === lastLine.current || said.current.has(line))) {
      return;
    }
    said.current.add(line);
    lastBubbleAt.current = now;
    lastLine.current = line;
    setBubble({ line, key: now });
    clearTimeout(bubbleTimer.current);
    bubbleTimer.current = setTimeout(() => setBubble(null), BUBBLE_MS);
  };

  useEffect(() => {
    let cancelled = false;
    let idleId = 0;
    let timer = 0;
    const load = () => {
      Promise.all(
        SOURCES.filter((src) => src !== center).map((src) => {
          const img = new Image();
          img.src = src;
          return img.decode ? img.decode().catch(() => {}) : Promise.resolve();
        })
      ).then(() => {
        if (cancelled) return;
        readyRef.current = true;
        setReady(true);
      });
    };
    const start = () => {
      if (window.requestIdleCallback) {
        idleId = window.requestIdleCallback(load, { timeout: 2000 });
      } else {
        timer = setTimeout(load, 300);
      }
    };
    if (document.readyState === "complete") start();
    else window.addEventListener("load", start, { once: true });
    return () => {
      cancelled = true;
      window.removeEventListener("load", start);
      if (idleId && window.cancelIdleCallback)
        window.cancelIdleCallback(idleId);
      clearTimeout(timer);
    };
  }, []);

  // Blink: only from the neutral frame, which is the one the eyes-closed
  // frame was drawn from — blinking out of a head turn would snap the head.
  useEffect(() => {
    let t = 0;
    let back = 0;
    const loop = () => {
      t = setTimeout(() => {
        if (frameRef.current === "center" && !document.hidden) {
          show.current("blink");
          back = setTimeout(() => {
            if (frameRef.current === "blink") show.current("center");
          }, 140);
        }
        loop();
      }, 2600 + Math.random() * 3600);
    };
    loop();
    return () => {
      clearTimeout(t);
      clearTimeout(back);
    };
  }, []);

  // Opening line, once, after the entrance has settled.
  useEffect(() => {
    const t = setTimeout(
      () => say.current("Hi, I'm Laxman 👋", { force: true }),
      1400
    );
    return () => clearTimeout(t);
  }, []);

  // Cursor tracking — fine pointers only.
  useEffect(() => {
    const root = rootRef.current;
    if (!root) return undefined;
    if (!window.matchMedia("(pointer: fine)").matches) return undefined;

    let raf = 0;
    let idle = 0;
    let work = 0;
    let dwell = 0;
    let zone = "center";
    let col = 1;
    let row = 1;
    let x = 0;
    let y = 0;

    // Drift: eased toward a target every frame, and the loop stops once it
    // has settled, so nothing runs while the cursor is still.
    const stack = root.querySelector(".gaze-stack");
    const light = root.querySelector(".gaze-light");
    const reduced = window.matchMedia("(prefers-reduced-motion: reduce)")
      .matches;
    let driftRaf = 0;
    let tx = 0;
    let ty = 0;
    let cx = 0;
    let cy = 0;
    const drift = () => {
      cx += (tx - cx) * 0.09;
      cy += (ty - cy) * 0.09;
      if (Math.abs(tx - cx) < 0.02 && Math.abs(ty - cy) < 0.02) {
        cx = tx;
        cy = ty;
        driftRaf = 0;
      } else {
        driftRaf = requestAnimationFrame(drift);
      }
      stack.style.transform = `translate3d(${cx.toFixed(2)}px, ${cy.toFixed(
        2
      )}px, 0)`;
      if (light) {
        const lx = (cx / DRIFT_X) * LIGHT_X;
        const ly = (cy / DRIFT_Y) * LIGHT_Y;
        light.style.transform = `translate3d(${lx.toFixed(1)}px, ${ly.toFixed(
          1
        )}px, 0)`;
      }
    };
    const aim = (nx, ny) => {
      if (reduced || !stack) return;
      tx = nx * DRIFT_X;
      ty = ny * DRIFT_Y;
      if (!driftRaf) driftRaf = requestAnimationFrame(drift);
    };

    // Pick a band for one axis, favouring the one we are already in.
    const band = (v, lo, hi, cur, m) => {
      const l = cur === 0 ? lo + m : lo - (cur === 1 ? m : 0);
      const h = cur === 2 ? hi - m : hi + (cur === 1 ? m : 0);
      return v < l ? 0 : v > h ? 2 : 1;
    };

    const zoneFor = (r) => {
      const fx = (x - r.left) / r.width;
      const fy = (y - r.top) / r.height;
      if (fx > FACE.x0 && fx < FACE.x1 && fy > FACE.y0 && fy < FACE.y1) {
        return "face";
      }
      const dx = (x - (r.left + r.width * EYE_X)) / r.width;
      const dy = (y - (r.top + r.height * EYE_Y)) / r.height;
      // Dead zones scale with the portrait, not fixed pixels.
      col = band(dx, -0.2, 0.2, col, HYSTERESIS);
      row = band(dy, -0.16, 0.22, row, HYSTERESIS);
      return GRID[row][col];
    };

    const update = () => {
      raf = 0;
      const r = root.getBoundingClientRect();
      aim(
        Math.max(
          -1,
          Math.min(1, (x - (r.left + r.width / 2)) / (r.width * 1.2))
        ),
        Math.max(-1, Math.min(1, (y - (r.top + r.height * EYE_Y)) / r.height))
      );
      if (lockRef.current) return;
      const next = zoneFor(r);
      if (next === zone) return;
      zone = next;
      clearTimeout(dwell);
      if (next === "face") {
        show.current("center");
        say.current(pick(FACE_LINES));
        return;
      }
      show.current(next);
      const lines = ZONE_LINES[next];
      if (lines) {
        dwell = setTimeout(() => {
          if (zone === next) say.current(pick(lines));
        }, DWELL_MS);
      }
    };

    const onMove = (e) => {
      x = e.clientX;
      y = e.clientY;
      // Coming back from his laptop, he looks up at you first.
      if (frameRef.current === "working" && !lockRef.current) zone = null;
      clearTimeout(idle);
      clearTimeout(work);
      idle = setTimeout(() => {
        aim(0, 0);
        if (lockRef.current) return;
        zone = "center";
        col = 1;
        row = 1;
        show.current("center");
      }, IDLE_MS);
      work = setTimeout(() => {
        if (lockRef.current) return;
        zone = "working";
        show.current("working");
        say.current(pick(WORK_LINES));
      }, WORK_MS);
      if (!raf) raf = requestAnimationFrame(update);
    };

    const onOver = (e) => {
      const cta = e.target.closest && e.target.closest(CTA_SELECTOR);
      if (!cta || lockRef.current === cta) return;
      lockRef.current = cta;
      show.current("smile");
      say.current(cta.getAttribute("data-gaze"), { force: true });
    };
    const onOut = (e) => {
      const cta = lockRef.current;
      // The lock can also be the string "tap", which ends on its own timer.
      if (!(cta instanceof Element) || cta.contains(e.relatedTarget)) return;
      lockRef.current = null;
      zone = null; // re-evaluate on the next move
      if (!raf) raf = requestAnimationFrame(update);
    };

    const onLeaveWindow = (e) => {
      if (e.relatedTarget) return;
      aim(0, 0);
      zone = "center";
      col = 1;
      row = 1;
      if (!lockRef.current) show.current("center");
    };

    window.addEventListener("mousemove", onMove, { passive: true });
    document.addEventListener("mouseover", onOver);
    document.addEventListener("mouseout", onOut);
    document.addEventListener("mouseout", onLeaveWindow);
    return () => {
      window.removeEventListener("mousemove", onMove);
      document.removeEventListener("mouseover", onOver);
      document.removeEventListener("mouseout", onOut);
      document.removeEventListener("mouseout", onLeaveWindow);
      cancelAnimationFrame(raf);
      cancelAnimationFrame(driftRaf);
      clearTimeout(idle);
      clearTimeout(work);
      clearTimeout(dwell);
    };
  }, []);

  // Touch: no cursor to follow, so he glances around on his own while the
  // hero is on screen. Skipped for reduced motion.
  useEffect(() => {
    const root = rootRef.current;
    if (!root) return undefined;
    if (window.matchMedia("(pointer: fine)").matches) return undefined;
    if (window.matchMedia("(prefers-reduced-motion: reduce)").matches) {
      return undefined;
    }

    let i = 0;
    let t = 0;
    let onScreen = true;
    const step = () => {
      t = setTimeout(() => {
        if (onScreen && !document.hidden && !lockRef.current) {
          i = (i + 1) % WANDER.length;
          show.current(WANDER[i]);
        }
        step();
      }, 2400 + Math.random() * 1400);
    };
    step();

    const io =
      typeof IntersectionObserver === "undefined"
        ? null
        : new IntersectionObserver(([entry]) => {
            onScreen = entry.isIntersecting;
          });
    if (io) io.observe(root);
    return () => {
      clearTimeout(t);
      if (io) io.disconnect();
    };
  }, []);

  useEffect(() => () => clearTimeout(bubbleTimer.current), []);

  // Tap / click on the portrait: big smile and a line.
  const smileTimer = useRef(0);
  const handleTap = () => {
    lockRef.current = "tap";
    show.current("smile");
    say.current(pick(TAP_LINES), { force: true });
    clearTimeout(smileTimer.current);
    smileTimer.current = setTimeout(() => {
      if (lockRef.current === "tap") lockRef.current = null;
      show.current("center");
    }, 1600);
  };
  useEffect(() => () => clearTimeout(smileTimer.current), []);

  const on = FRAMES[frame];
  const under = prev ? FRAMES[prev] : null;

  return (
    <div
      className={`gaze-portrait${shown ? " is-shown" : ""}`}
      ref={rootRef}
      onClick={handleTap}
      role="img"
      aria-label="Illustrated portrait of Laxman at his laptop, following your cursor"
    >
      <div className="gaze-glow" aria-hidden="true" />
      <div className="gaze-light" aria-hidden="true" />
      <div className="gaze-floor" aria-hidden="true" />
      <div className="gaze-stack" aria-hidden="true">
        {(ready ? SOURCES : [center]).map((src) => (
          <img
            key={src}
            src={src}
            alt=""
            draggable="false"
            decoding={src === center ? "sync" : "async"}
            ref={src === center ? firstImgRef : undefined}
            onLoad={src === center ? () => setShown(true) : undefined}
            className={`gaze-frame${src === on ? " is-on" : ""}${
              src !== on && src === under ? " is-prev" : ""
            }`}
          />
        ))}
      </div>
      {bubble && (
        <div className="gaze-bubble" key={bubble.key} aria-hidden="true">
          {bubble.line}
        </div>
      )}
    </div>
  );
}
